// 《唐诗三百首》里也有的 (登鹳雀楼、静夜思、枫桥夜泊……) 用那边写好的; 题目不一样的 (渭城曲 / 送元二使安西、泊秦淮 / 秦淮夜泊) 换掉题目的注释。
// 书里有好几首同名的 (四首《清明》), 键写「题目|作者」。tests/poem-yizhu.test.js 会检查每条都找得到
