    yi: ['凉风吹着夜雨，寒冷的树林在风中萧萧作响。', '这时正在高大的厅堂里举行宴会，我哪能忘记自己已是迟暮之年。', '军营里适合舞剑助兴，边塞上看重的是胡笳的乐音。', '如果不来做这守边的将领，又怎么知道皇上的恩遇有多深呢？'],
    bg: '唐玄宗开元初年，张说做中书令（宰相），因为和另一位宰相姚崇不和，被贬出京城，后来到幽州做都督。这首诗写他在幽州都督府夜宴的情景。末两句表面上是感谢皇恩，一般认为其实含着被贬在外的不平。',
