    yi: ['没有花赏，也没有酒喝，就这样过清明，冷冷清清，像个山野里的和尚。', '昨天从邻居家讨来了新火，今天一早就在窗前点起了读书的灯。'],
    bg: '王禹偁是北宋初年的诗人，为人正直，几次被贬。这首诗一般认为是他被贬到商州（今陕西商洛）时写的，那时他很穷，清明节连花和酒都没有。也有人认为这首诗是魏野写的。',
