    bg: '洪咨夔是南宋人，做过翰林学士、知制诰，负责替皇帝起草诏书。起草重要诏书时，要把翰林院锁起来保密，叫「宣锁」。这首诗又题作《六月十六日宣锁》，写他一夜起草两位宰相的任命诏书。',
