    yi: ['上朝的路上点着白亮的蜡烛，京城的大路长长地通向宫中，皇城里春色正浓，天刚蒙蒙亮。', '千万条柔弱的柳枝垂在宫门旁，婉转啼叫的黄莺绕着宫殿飞来飞去。', '百官腰间的剑和玉佩随着步子在玉阶上叮当作响，衣帽上都沾满了御炉里的香气。', '我们一同沐浴着皇恩在中书省做事，每天早上提笔写文章，侍奉君王。'],
