    yi: ['我在月陂的堤岸上四处徘徊，北边有一座高耸入云的百尺高台。', '万物都随着秋天的气象改变了，在傍晚的凉意里，姑且打开一壶酒。', '水中央的云影悠闲地互相映照，树林里的泉水声静静地传来。', '世上的事变化无常，哪里值得计较，只要遇到佳节，就约好再一起来。'],
    bg: '程颢晚年住在洛阳，这首诗写他和朋友秋天游月陂的情景。',
