    yi: ['满船的月光好像浸满了整个天空，绿水平静，没有一丝波纹，夜里的凉气直往上冒。', '作诗的灵感在桅杆的影子里时沉时浮，梦魂在摇橹的声音中摇荡。', '星星冷冷清清地映在碧绿的潭水里，大雁在吹过红蓼的风中悲鸣。', '几点渔灯靠在古老的岸边，断桥边，露水从梧桐叶上滴落下来。'],
    bg: '戴复古是南宋的江湖诗人，一生没有做官，在各地漫游。这首诗写他月夜坐船时看到的景色。',
