    yi: ['拂晓时分，天上的云彩凄凉地飘动，长安的宫殿高耸在秋空里。', '天上还有几点残星，一行大雁横过边塞；不知是谁靠着楼栏，吹起一声长笛。', '篱笆边的紫菊半开着，静静的；水中小洲上的莲花，红色的花瓣都落光了，好像在发愁。', '家乡的鲈鱼正好吃，我却不回去，白白地像楚囚一样戴着南方的帽子，困在这里。'],
    bg: '赵嘏考进士没有考中，在长安住了很久，这首诗写于那个时候。杜牧特别欣赏「长笛一声人倚楼」这一句，叫他「赵倚楼」。',
