    yi: ['夏天火红的云还像奇峰一样没有散去，我斜靠在枕头上，忽然被吹落第一片树叶的秋风惊动。', '好几处园林都变得萧瑟冷落，不知谁家的捣衣声在寂静中传来。', '蝉声断断续续，对着残月悲鸣；萤火虫的光忽高忽低，照着傍晚的天空。', '我写好了赋，盼着能再献给朝廷，深夜里抓着头发，感叹自己像飞蓬一样漂泊。'],
    bg: '《千家诗》写作杜甫的，可是杜甫的集子里没有这首诗。南宋的类书《锦绣万花谷》引前四句时，注明「出孙仅」。孙仅是北宋初年的人，所以这首诗很可能不是杜甫写的。',
