    yi: ['明亮的月亮像宝镜一样升上天空，云间的风声静悄悄的，没有一点声响。', '中秋把秋色平分，一轮圆月正满，长久地伴着天上的大路，照亮千里。', '月中的玉兔不必再从弦月边落下，吞月的蟾蜍也别再出现在眼前。', '我打算约你一起乘上仙槎去天河，等到银河清澈见底的时候。'],
    bg: '李朴是北宋末年人。据《宋史》记载，宋钦宗即位后很器重他，半年里给他升了五次官。一般认为这首诗写于那以后的一个中秋。',
