    yi: ['丈夫在战乱中死了，她一个人守着茅草屋，穿着粗麻布的衣裙，头发枯黄。', '桑树柘树早就荒废了，还得交蚕丝税；田园全都荒了，官府还要征青苗税。', '她常常挖来野菜，连根一起煮着吃；临时砍些湿柴，连叶子一起烧。', '即使逃到深山里最深的地方，也没有办法躲开赋税和劳役。'],
    bg: '唐朝末年，军阀混战，赋税繁重，百姓苦不堪言。杜荀鹤写了不少反映百姓苦难的诗，这首写一个丈夫死于战乱的寡妇，逃到深山里也躲不开官府的盘剥。',
