    yi: ['霜落在芝城，柳影稀疏，我情意恳切地送客人出了鄱阳湖。', '天师的雷霆大印装在黄金匣里锁着，日月符箓用红锦的套子缠着。', '他清早在天上骑着一只仙鹤飞行，夜里在人间住宿，像王乔那样把双凫化作鞋子脱下。', '匆匆回到神仙府里，请替我问一声：蟠桃熟了没有？'],
    bg: '朱权是明太祖朱元璋的第十七个儿子，封为宁王，后来住在南昌，晚年信奉道教。这首诗是他送龙虎山的张天师回山时写的。',
