    bg: '这首诗的作者是明世宗朱厚熜（嘉靖皇帝）。嘉靖年间，安南（今越南）发生内乱，世宗派毛伯温带兵南征，写了这首诗为他送行。毛伯温到了边境，用威势和计谋让对方投降，没有打仗就平定了这件事。',
